import os
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


@dataclass
class FieldValidationResult:
    required_fields_present: bool
    confidence_scores_valid: bool
    missing_required_fields: List[str] = field(default_factory=list)
    invalid_confidence_fields: List[str] = field(default_factory=list)
    extracted_fields: Dict[str, Any] = field(default_factory=dict)
    raw_response: Optional[Dict[str, Any]] = None


def _safe_getattr(obj: Any, name: str, default: Any = None) -> Any:
    try:
        return getattr(obj, name, default)
    except Exception:
        return default


def _to_float(value: Any) -> Optional[float]:
    try:
        if value is None:
            return None
        return float(value)
    except Exception:
        return None


def validate_structured_document(
    document_url: str,
    *,
    required_fields: Optional[List[str]] = None,
    confidence_threshold: float = 0.5,
) -> FieldValidationResult:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        analyze_request={"urlSource": document_url},
    )
    result = poller.result()

    extracted: Dict[str, Any] = {}
    field_confidence: Dict[str, Optional[float]] = {}

    docs = _safe_getattr(result, "documents", []) or []
    if docs:
        fields = _safe_getattr(docs[0], "fields", {}) or {}
        for name, field_obj in fields.items():
            value = _safe_getattr(field_obj, "value", None)
            if value is None:
                value = _safe_getattr(field_obj, "content", None)
            if value is None:
                value = _safe_getattr(field_obj, "spans", None)
            extracted[name] = value
            field_confidence[name] = _to_float(_safe_getattr(field_obj, "confidence", None))

    if required_fields is None:
        required_fields = [
            "InvoiceId",
            "InvoiceDate",
            "DueDate",
            "VendorName",
            "CustomerName",
            "InvoiceTotal",
        ]

    missing_required_fields = [name for name in required_fields if name not in extracted or extracted[name] in (None, "", [])]

    invalid_confidence_fields: List[str] = []
    for name in required_fields:
        conf = field_confidence.get(name)
        if conf is None or conf < confidence_threshold:
            invalid_confidence_fields.append(name)

    raw_response = None
    try:
        raw_response = result.as_dict() if hasattr(result, "as_dict") else None
    except Exception:
        raw_response = None

    return FieldValidationResult(
        required_fields_present=len(missing_required_fields) == 0,
        confidence_scores_valid=len(invalid_confidence_fields) == 0,
        missing_required_fields=missing_required_fields,
        invalid_confidence_fields=invalid_confidence_fields,
        extracted_fields=extracted,
        raw_response=raw_response,
    )
